const plan = $('Consulta demo').first().json;
const rows = $input.first().json.body;
if (!Array.isArray(rows) || rows.length > 2 || rows.some((r,i) => r.sender_kind !== 'customer' || r.body !== plan.entradas[i].mensaje)) throw new Error('La conversación contiene datos distintos a la prueba.');
return plan.entradas.map(e => ({json:{...e,conversation_id:plan.conversation_id}}));

const turnos = $input.all().map(i=>i.json);
if(turnos.length !== 2 || turnos[0].turno !== 1 || turnos[1].turno !== 2) throw new Error('Faltan resultados ordenados de ambos turnos.');
const normal = v => String(v ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
for (const d of turnos) {
  const busqueda = normal([d.vehiculo_buscado,...(d.caracteristicas ?? [])].join(' '));
  if (!busqueda.includes('corolla') || !busqueda.includes('automatic') || d.presupuesto_importe !== 20000 ||
      d.presupuesto_moneda !== 'USD' || d.presupuesto_alcance !== 'valor_total')
    throw new Error('Vehículo, transmisión o presupuesto incorrecto en turno '+d.turno);
}
const d = turnos[1];
if (!/\b(15|quince)\b/.test(normal(d.plazo_compra)) || !normal(d.plazo_compra).includes('dia') ||
    d.tiene_usado !== false || d.decision_entrega_usado !== 'descartada' || d.necesita_financiacion !== false)
  throw new Error('Revisar plazo, entrega de usado o financiación en el segundo turno.');
return [{json:{verificado:true,turnos}}];

const entrada = $('Entrada actual').first(0,$runIndex).json;
const actual = $('Registrar entrada').first(0,$runIndex).json.body[0];
const plan = $('Consulta demo').first().json;
if (actual.conversation_id !== plan.conversation_id || !actual.message_id || !Number.isSafeInteger(actual.history_position)) throw new Error('Ingreso sin identificador o corte válido.');
const rows = $input.all().flatMap(p => {
  if (!Array.isArray(p.json.body)) throw new Error('Página de historial inválida.');
  return p.json.body;
});
let anterior = 0;
const ids = new Set();
const historial = rows.map(r => {
  if (!Number.isSafeInteger(r.history_position) || r.history_position <= anterior || r.history_position >= actual.history_position ||
      !r.message_id || r.message_id === actual.message_id || ids.has(r.message_id) || !['bot','customer'].includes(r.sender_kind))
    throw new Error('Página fuera de orden, autor inválido o mensaje repetido.');
  anterior = r.history_position; ids.add(r.message_id);
  return (r.sender_kind === 'customer' ? 'Cliente: ' : 'Bot: ') + r.body;
});
if (rows.length !== entrada.turno - 1 || (entrada.turno === 2 && (rows[0].sender_kind !== 'customer' || rows[0].body !== plan.entradas[0].mensaje))) throw new Error('Historial inesperado para el turno comercial.');
return [{json:{turno:entrada.turno,historial:historial.join('\n'),mensaje:entrada.mensaje,message_id:actual.message_id,corte:actual.history_position,anteriores:rows.map(r=>r.message_id)}}];

